function posterStyle(m){
 return `background:linear-gradient(135deg,${m.color},#111827);`;
}
function render(){
 const q=document.getElementById("search").value.toLowerCase().trim();
 const g=document.getElementById("genre").value;
 const list=movies.filter(m=>(g==="전체"||m.genre===g)&&
   (!q||(m.title+m.genre+m.desc).toLowerCase().includes(q)));
 document.getElementById("count").textContent=`${list.length}편`;
 const grid=document.getElementById("grid");
 if(!list.length){grid.innerHTML='<div class="empty" style="grid-column:1/-1">😢 조건에 맞는 영화가 없어요.</div>';return}
 grid.innerHTML=list.map((m,i)=>`
 <article class="card" onclick="showMovie(${movies.indexOf(m)})">
   <div class="poster" style="${posterStyle(m)};--poster-color:${m.color}">
      <div class="original-poster" aria-label="${m.title} 자체 제작 포스터">
  <div class="poster-glow"></div>
  <div class="poster-lines"></div>
  <span class="poster-genre">${m.genre}</span>
  <div class="poster-symbol">${m.genre==="액션"?"⚡":m.genre==="SF"?"✦":m.genre==="로맨스"?"♥":m.genre==="코미디"?"☻":m.genre==="스릴러"?"◈":m.genre==="애니메이션"?"★":"◆"}</div>
  <strong>${m.title}</strong>
  <small>${m.year} · MOVIEPICK ORIGINAL</small>
</div>
      <strong>${m.title}</strong>
    </div>
   <div class="info"><div class="meta">${m.year} · ⭐ ${m.rating} · ${m.genre}</div>
   <div class="desc">${m.desc}</div><div class="tags"><span class="tag">추천</span><span class="tag">${m.genre}</span></div></div>
 </article>`).join("");
}
